def create_levels(apps, schema_editor):
    GradeLevel = apps.get_model("inventory", "GradeLevel")
    for order, (domain, code, name, description) in enumerate(LEVELS):
        GradeLevel.objects.get_or_create(
            domain=domain,
            code=code,
            defaults={"name": name, "description": description, "order": order},
        )


